// Only game data may leave browser storage. Never collect tokens or other sites' data.
const exact = new Set(['digit-span-best:v1','francais5000:v1','francais1000sentences:v1','deutsch5000:v1','deutsch1000sentences:v1','japanese:kana:v1','japanese:kanji:v1','spanish5000:v1','spanish1000sentences:v1','italian5000:v1','italian1000sentences:v1','greek5000:v1','greek1000sentences:v1','korean:hangul:v1','korean5000:v1','economics3500:v1','trivia20000:v1','programming5000:v1','quant5000:v1']);
export function gameKey(key){return exact.has(key)||/^(french|german|japanese|spanish|italian|greek|korean):mode:v1$/.test(key)||/^weekly-arithmetic-v1:(settings|(?:count|practice):\d{4}-\d{2}-\d{2}:[\w:-]+)$/.test(key)}
export function snapshot(storage){const out={};for(let i=0;i<storage.length;i++){const key=storage.key(i);if(gameKey(key))out[key]=storage.getItem(key)}return Object.fromEntries(Object.entries(out).sort(([a],[b])=>a.localeCompare(b)))}
export function validate(value){if(!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).length>10000)throw Error('Invalid progress');let bytes=0;for(const [key,text]of Object.entries(value)){if(!gameKey(key)||typeof text!=='string')throw Error('Invalid game data');bytes+=text.length;if(bytes>15000000)throw Error('Progress is too large');if(key.endsWith(':mode:v1')){if(!/^[a-zA-Z]{1,32}$/.test(text))throw Error('Invalid mode')}else JSON.parse(text)}return value}
export function same(a,b){return JSON.stringify(Object.fromEntries(Object.entries(a).sort()))===JSON.stringify(Object.fromEntries(Object.entries(b).sort()))}
export async function encode(value){const text=JSON.stringify(validate(value));if(!globalThis.CompressionStream)return 'j:'+text;const blob=await new Response(new Blob([text]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer();let raw='';const bytes=new Uint8Array(blob);for(let i=0;i<bytes.length;i+=16384)raw+=String.fromCharCode(...bytes.subarray(i,i+16384));return 'g:'+btoa(raw)}
export async function decode(text){if(typeof text!=='string'||text.length>700000)throw Error('Invalid cloud save');let json;if(text.startsWith('j:'))json=text.slice(2);else if(text.startsWith('g:')){const raw=atob(text.slice(2));const stream=new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'));const reader=stream.getReader(),chunks=[];let size=0;while(true){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>15000000){await reader.cancel();throw Error('Progress is too large')}chunks.push(value)}json=await new Blob(chunks).text()}else throw Error('Unknown save format');return validate(JSON.parse(json))}
export function choose(base,local,remote){if(same(local,remote))return 'equal';if(base&&same(local,base))return 'remote';if(base&&same(remote,base))return 'local';if(!Object.keys(local).length)return 'remote';if(!Object.keys(remote).length)return 'local';return 'conflict'}
